require "rails_helper"

RSpec.describe RelayJob do
  # No token is written to a payload or a log line.
  it "writes no service token to the request body or the log when the snapshot endpoint refuses the batch" do
    service_token = "service-#{SecureRandom.hex(24)}"
    extra_credential = "held-#{SecureRandom.hex(24)}"
    now = Time.current
    OutboxSnapshot.insert_all!([{
      id: 41, project_id: 1, user_id: 1, work_date: "2026-03-02", duration: 60.0,
      bill_status: "unbilled", review_status: "not_required", locked: false, source: "manual",
      source_metadata: {}, proof_metadata: {}, created_at: now, updated_at: now,
      company_id: 1, version: 1, generation: 1
    }])
    bodies = []
    WebMock.stub_request(:post, "http://snapshots.test/internal/v1/timekeeping/entry-snapshots").to_return do |request|
      bodies << request.body
      { status: 401, headers: { "Content-Type" => "application/json" },
        body: JSON.generate(reason: "Bearer #{service_token}\nforged #{extra_credential}") }
    end

    io = StringIO.new
    logger = ActiveSupport::TaggedLogging.new(ActiveSupport::Logger.new(io))
    logger.level = Logger::DEBUG
    previous = [Rails.logger, ActiveJob::Base.logger]
    marker = "relay-marker-#{SecureRandom.hex(8)}"
    begin
      Rails.logger = logger
      ActiveJob::Base.logger = logger
      with_timekeeping_env(
        Timekeeping::Environment::SERVICE_TOKEN => service_token,
        Timekeeping::Environment::SERVICE_CREDENTIALS => extra_credential,
        Timekeeping::Environment::MONOLITH_SNAPSHOT_URL => "http://snapshots.test"
      ) do
        Rails.logger.info(marker)
        described_class.perform_now
      end
    ensure
      Rails.logger, ActiveJob::Base.logger = previous
    end

    expect(io.string).to include(marker)
    expect(io.string).to include("401")
    expect(bodies.size).to eq(1)
    [service_token, extra_credential].each do |credential|
      expect(io.string).not_to include(credential)
      expect(bodies.join).not_to include(credential)
    end
    expect(OutboxSnapshot.where(sent_at: nil).count).to eq(1)
  end
end

require_relative "../../../spec/support/timekeeping/fake_relay"

RSpec.describe RelayJob, "delivery to the projection endpoint" do
  let(:relay_job_snapshot_url) { "http://projection.relay-job.test" }
  let(:relay_job_fake_timekeeping) { TimekeepingContract::FakeTimekeeping.new }
  let(:relay_job_credential) do
    relay_job_fake_timekeeping.add_service(company_id: nil, name: "timekeeping", operations: ["deliver"])
  end
  let(:relay_job_projection) { TimekeepingContract::FakeRelay.new(source: relay_job_fake_timekeeping) }
  let(:relay_job_posted_positions) { [] }

  # Forwards every POST the job makes to the in-memory projection endpoint.
  before do
    WebMock.stub_request(:post, "#{relay_job_snapshot_url}/internal/v1/timekeeping/entry-snapshots").to_return do |request|
      body = JSON.parse(request.body)
      relay_job_posted_positions.concat(body.fetch("snapshots").map { |item| item.fetch("outbox_position") })
      answer = relay_job_projection.call("POST", request.uri.path,
                                         headers: { "Authorization" => request.headers["Authorization"],
                                                    "Idempotency-Key" => request.headers["Idempotency-Key"] },
                                         body:)
      { status: answer.status, headers: { "Content-Type" => "application/json" }, body: JSON.generate(answer.body) }
    end
  end

  def insert_relay_job_snapshot(position, entry_id:, generation: TimekeepingContract::FakeTimekeeping::INITIAL_GENERATION)
    stamp = Time.utc(2026, 3, 2, 9)
    OutboxSnapshot.insert_all!([{
      outbox_position: position, id: entry_id, project_id: 3, user_id: 4, work_date: "2026-03-02", duration: 60.0,
      bill_status: "unbilled", review_status: "not_required", locked: false, source: "manual",
      source_metadata: {}, proof_metadata: {}, created_at: stamp, updated_at: stamp,
      company_id: 1, version: 1, generation:
    }])
  end

  def run_relay_job
    with_timekeeping_env(
      Timekeeping::Environment::MONOLITH_SNAPSHOT_URL => relay_job_snapshot_url,
      Timekeeping::Environment::SERVICE_TOKEN => relay_job_credential
    ) { described_class.perform_now }
  end

  it "delivers real outbox rows in outbox_position order and marks them sent after the 200" do
    insert_relay_job_snapshot(12, entry_id: 503)
    insert_relay_job_snapshot(3, entry_id: 501)
    insert_relay_job_snapshot(7, entry_id: 502)

    run_relay_job

    expect(relay_job_posted_positions).to eq([3, 7, 12])
    expect(OutboxSnapshot.where(sent_at: nil)).to be_empty
    expect(relay_job_projection.projected_entry(502)).to include("id" => 502, "version" => 1, "company_id" => 1)
  end

  it "leaves every row unsent when the projection endpoint answers 409 stale_generation" do
    insert_relay_job_snapshot(1, entry_id: 601)
    insert_relay_job_snapshot(2, entry_id: 602)
    relay_job_projection.generation = TimekeepingContract::FakeTimekeeping::INITIAL_GENERATION + 1

    run_relay_job

    expect(relay_job_posted_positions).to eq([1, 2])
    expect(OutboxSnapshot.where(sent_at: nil).count).to eq(2)
    expect(relay_job_projection.projected_entry(601)).to be_nil
  end

  it "sends nothing while another connection holds the relay lock" do
    insert_relay_job_snapshot(1, entry_id: 701)
    other_connection = PG.connect(Timekeeping::Environment.database_url)
    begin
      other_connection.exec_params("SELECT pg_advisory_lock($1)", [described_class::RELAY_LOCK_KEY])

      run_relay_job

      expect(relay_job_posted_positions).to be_empty
      expect(OutboxSnapshot.where(sent_at: nil).count).to eq(1)
    ensure
      other_connection.close
    end

    run_relay_job

    expect(relay_job_posted_positions).to eq([1])
  end
end
